// Append as a Session 17 section in App/Program.cs.
var timesheetEmployee = new Employee(17, "Avery", new Address { City = "Springfield" });
var timesheet = new TimeSheet(timesheetEmployee);

var matchingEntry = new ClockEntry(17, new DateTime(2026, 1, 17, 8, 0, 0));
bool matchingAdded = timesheet.TryAdd(matchingEntry);
Console.WriteLine($"Matching entry added: {matchingAdded}");

var mismatchedEntry = new ClockEntry(99, new DateTime(2026, 1, 17, 9, 0, 0));
bool mismatchedAdded = timesheet.TryAdd(mismatchedEntry);
Console.WriteLine($"Mismatched entry added: {mismatchedAdded}");
